"""Curated offline content for Helsinki in Italian, English, French and Spanish."""

CITY_ID = "helsinki"


def _attraction(block, zone, level, names, descriptions, lat, lon, minutes, kind, url=None):
    return {
        "city": CITY_ID, "block_id": block, "zone": zone, "category_level": level,
        "name": names[0], "name_en": names[1], "name_fr": names[2], "name_es": names[3],
        "description": descriptions[0], "description_en": descriptions[1],
        "description_fr": descriptions[2], "description_es": descriptions[3],
        "latitude": lat, "longitude": lon, "estimated_visit_time": minutes,
        "tags": [kind, zone], "attraction_type": kind, "ticket_url": url,
    }


_A = _attraction
ATTRACTIONS = [
    _A(201, "senate_market", 1, ("Cattedrale di Helsinki", "Helsinki Cathedral", "Cathédrale d'Helsinki", "Catedral de Helsinki"),
       ("La cattedrale luterana domina Piazza del Senato con la grande scalinata e le cupole verdi. L'interno è volutamente sobrio e l'accesso può essere limitato durante le funzioni.", "The Lutheran cathedral dominates Senate Square with its grand steps and green domes. Its interior is deliberately restrained and access may be limited during services.", "La cathédrale luthérienne domine la place du Sénat avec son grand escalier et ses dômes verts. Son intérieur est volontairement sobre et l'accès peut être limité pendant les offices.", "La catedral luterana domina la Plaza del Senado con su gran escalinata y sus cúpulas verdes. El interior es deliberadamente sobrio y el acceso puede limitarse durante los oficios."), 60.1705, 24.9520, 45, "chiesa", "https://helsingintuomiokirkko.fi/en/"),
    _A(201, "senate_market", 1, ("Piazza del Senato", "Senate Square", "Place du Sénat", "Plaza del Senado"),
       ("Il complesso neoclassico di Carl Ludvig Engel riunisce cattedrale, università e palazzo del governo. È il punto migliore per leggere la nascita della Helsinki monumentale ottocentesca.", "Carl Ludvig Engel's Neoclassical ensemble brings together the cathedral, university and Government Palace. It is the best place to understand the birth of monumental nineteenth-century Helsinki.", "L'ensemble néoclassique de Carl Ludvig Engel réunit cathédrale, université et palais du gouvernement. C'est le meilleur endroit pour comprendre la naissance de la Helsinki monumentale du XIXe siècle.", "El conjunto neoclásico de Carl Ludvig Engel reúne la catedral, la universidad y el Palacio de Gobierno. Es el mejor lugar para comprender el nacimiento de la Helsinki monumental del siglo XIX."), 60.1695, 24.9522, 35, "piazza"),
    _A(201, "senate_market", 1, ("Cattedrale Uspenski", "Uspenski Cathedral", "Cathédrale Ouspenski", "Catedral de Uspenski"),
       ("La più grande cattedrale ortodossa dell'Europa occidentale si alza su una roccia di Katajanokka. Mattoni rossi, cupole dorate e iconostasi raccontano il legame storico con l'Impero russo.", "Western Europe's largest Orthodox cathedral rises on a Katajanokka rock outcrop. Red brick, golden domes and its iconostasis reflect the city's historic ties with the Russian Empire.", "La plus grande cathédrale orthodoxe d'Europe occidentale s'élève sur un rocher de Katajanokka. Briques rouges, dômes dorés et iconostase rappellent les liens historiques avec l'Empire russe.", "La mayor catedral ortodoxa de Europa occidental se alza sobre una roca de Katajanokka. El ladrillo rojo, las cúpulas doradas y el iconostasio recuerdan los vínculos históricos con el Imperio ruso."), 60.1686, 24.9600, 45, "chiesa", "https://www.hos.fi/en/uspenski-cathedral/"),
    _A(201, "senate_market", 2, ("Piazza del Mercato", "Market Square", "Place du Marché", "Plaza del Mercado"),
       ("Il mercato sul porto è una buona introduzione a salmone, frutti di bosco e artigianato finlandese. Da qui partono anche i traghetti per Suomenlinna, quindi l'atmosfera cambia molto durante la giornata.", "The harbour market is a good introduction to Finnish salmon, berries and crafts. Ferries to Suomenlinna also leave from here, so its atmosphere changes markedly through the day.", "Le marché du port est une bonne introduction au saumon, aux baies et à l'artisanat finlandais. Les ferries pour Suomenlinna partent aussi d'ici, si bien que l'ambiance change beaucoup au fil de la journée.", "El mercado del puerto es una buena introducción al salmón, las bayas y la artesanía finlandesa. Desde aquí también salen los ferris a Suomenlinna, por lo que el ambiente cambia mucho durante el día."), 60.1672, 24.9544, 45, "mercato"),
    _A(201, "senate_market", 2, ("Antico Mercato Coperto", "Old Market Hall", "Vieux Marché couvert", "Antiguo Mercado Cubierto"),
       ("Aperto nel 1889, raccoglie banchi alimentari, caffè e specialità locali in uno spazio storico compatto. È una tappa utile anche con pioggia o freddo.", "Opened in 1889, it gathers food stalls, cafés and local specialities in a compact historic hall. It is also a useful stop in rain or cold weather.", "Ouvert en 1889, il rassemble étals, cafés et spécialités locales dans une halle historique compacte. C'est aussi une halte pratique par temps froid ou pluvieux.", "Inaugurado en 1889, reúne puestos, cafeterías y especialidades locales en un mercado histórico compacto. También es una parada práctica con lluvia o frío."), 60.1664, 24.9523, 45, "mercato", "https://vanhakauppahalli.fi/en/"),
    _A(201, "senate_market", 3, ("Parco Esplanadi", "Esplanadi Park", "Parc de l'Esplanade", "Parque Esplanadi"),
       ("Il salotto verde del centro collega il porto alle vie commerciali tra alberi, chioschi e musica estiva. La passeggiata consente di osservare con calma le facciate del centro storico.", "The green drawing room of the centre links the harbour with the shopping streets through trees, kiosks and summer music. Its promenade is ideal for observing the historic façades at an easy pace.", "Le salon vert du centre relie le port aux rues commerçantes entre arbres, kiosques et musique estivale. Sa promenade permet d'observer tranquillement les façades historiques.", "El salón verde del centro conecta el puerto con las calles comerciales entre árboles, quioscos y música de verano. El paseo permite observar con calma las fachadas históricas."), 60.1675, 24.9475, 35, "parco"),

    _A(202, "suomenlinna", 1, ("Fortezza marina di Suomenlinna", "Suomenlinna Sea Fortress", "Forteresse maritime de Suomenlinna", "Fortaleza marítima de Suomenlinna"),
       ("La fortezza UNESCO occupa più isole con bastioni, tunnel, musei e circa sei chilometri di mura. L'accesso all'area è gratuito, mentre musei e visite guidate richiedono biglietti separati.", "The UNESCO fortress spreads across several islands with bastions, tunnels, museums and roughly six kilometres of walls. The site itself is free, while museums and guided tours require separate tickets.", "La forteresse UNESCO s'étend sur plusieurs îles avec bastions, tunnels, musées et environ six kilomètres de remparts. L'accès au site est gratuit, mais les musées et visites guidées sont payants.", "La fortaleza UNESCO ocupa varias islas con bastiones, túneles, museos y unos seis kilómetros de murallas. El acceso al recinto es gratuito, mientras que los museos y visitas guiadas requieren entrada."), 60.1458, 24.9875, 150, "fortezza", "https://suomenlinna.fi/en/"),
    _A(202, "suomenlinna", 1, ("Porta del Re", "King's Gate", "Porte du Roi", "Puerta del Rey"),
       ("La porta cerimoniale affacciata sul mare fu costruita nel Settecento ed è uno dei simboli della fortezza. Si raggiunge lungo la Blue Route attraversando la parte più scenografica delle fortificazioni.", "The ceremonial sea gate was built in the eighteenth century and is one of the fortress's symbols. It is reached along the Blue Route through the most scenic part of the fortifications.", "La porte cérémonielle tournée vers la mer fut construite au XVIIIe siècle et constitue l'un des symboles de la forteresse. On l'atteint par la Blue Route à travers la partie la plus spectaculaire des fortifications.", "La puerta ceremonial frente al mar fue construida en el siglo XVIII y es uno de los símbolos de la fortaleza. Se llega por la Blue Route, atravesando la parte más escénica de las fortificaciones."), 60.1428, 24.9850, 35, "fortificazione"),
    _A(202, "suomenlinna", 2, ("Museo di Suomenlinna", "Suomenlinna Museum", "Musée de Suomenlinna", "Museo de Suomenlinna"),
       ("Il museo principale ricostruisce le fasi svedese, russa e finlandese della fortezza. È la visita migliore per dare un ordine storico a ciò che si vede all'aperto.", "The main museum explains the fortress's Swedish, Russian and Finnish periods. It is the best visit for giving historical order to what is seen outdoors.", "Le musée principal retrace les périodes suédoise, russe et finlandaise de la forteresse. C'est la meilleure visite pour organiser historiquement ce que l'on voit dehors.", "El museo principal explica las etapas sueca, rusa y finlandesa de la fortaleza. Es la mejor visita para ordenar históricamente lo que se observa al aire libre."), 60.1456, 24.9884, 60, "museo", "https://suomenlinna.fi/en/visitor/museums/suomenlinna-museum/"),
    _A(202, "suomenlinna", 2, ("Sottomarino Vesikko", "Submarine Vesikko", "Sous-marin Vesikko", "Submarino Vesikko"),
       ("Il sottomarino restaurato mostra in spazi strettissimi la vita dell'equipaggio durante la Seconda guerra mondiale. È stagionale e gli interni non sono adatti a chi soffre gli ambienti angusti.", "The restored submarine reveals crew life during the Second World War in extremely tight quarters. It is seasonal and the interior does not suit visitors uncomfortable in confined spaces.", "Le sous-marin restauré montre la vie de l'équipage pendant la Seconde Guerre mondiale dans des espaces très étroits. Il est saisonnier et déconseillé aux personnes mal à l'aise dans les lieux confinés.", "El submarino restaurado muestra la vida de la tripulación durante la Segunda Guerra Mundial en espacios muy reducidos. Es estacional y no resulta adecuado para quien se sienta incómodo en lugares cerrados."), 60.1438, 24.9855, 40, "museo", "https://suomenlinna.fi/en/visitor/museums/submarine-vesikko/"),
    _A(202, "suomenlinna", 3, ("Chiesa di Suomenlinna", "Suomenlinna Church", "Église de Suomenlinna", "Iglesia de Suomenlinna"),
       ("Nata come chiesa ortodossa russa, fu trasformata in edificio luterano dopo l'indipendenza finlandese. La torre svolge anche la funzione di faro, un caso raro nel mondo.", "Built as a Russian Orthodox church, it became Lutheran after Finnish independence. Its tower also serves as a lighthouse, an unusual combination worldwide.", "Construite comme église orthodoxe russe, elle devint luthérienne après l'indépendance finlandaise. Sa tour sert aussi de phare, une combinaison rare au monde.", "Construida como iglesia ortodoxa rusa, pasó a ser luterana tras la independencia finlandesa. Su torre también funciona como faro, una combinación poco común en el mundo."), 60.1480, 24.9873, 30, "chiesa"),
    _A(202, "suomenlinna", 3, ("Grande Corte e bacino di carenaggio", "Great Courtyard and Dry Dock", "Grande Cour et cale sèche", "Gran Patio y dique seco"),
       ("La corte conserva il cuore monumentale della fortezza, mentre il bacino di carenaggio è tra i più antichi ancora attivi in Europa. In inverno vi vengono custodite imbarcazioni tradizionali in legno.", "The courtyard preserves the monumental heart of the fortress, while the dry dock is among Europe's oldest still in use. Traditional wooden vessels are kept there in winter.", "La cour conserve le cœur monumental de la forteresse, tandis que la cale sèche compte parmi les plus anciennes encore actives d'Europe. Des bateaux traditionnels en bois y sont abrités en hiver.", "El patio conserva el corazón monumental de la fortaleza, mientras que el dique seco es uno de los más antiguos de Europa todavía en uso. En invierno alberga embarcaciones tradicionales de madera."), 60.1450, 24.9845, 40, "sito storico"),

    _A(203, "toolo_culture", 1, ("Chiesa nella Roccia", "Temppeliaukio Church", "Église Temppeliaukio", "Iglesia de Temppeliaukio"),
       ("La chiesa è scavata direttamente nel granito e coperta da una cupola di rame che diffonde la luce naturale. L'acustica la rende anche una sala da concerto molto apprezzata.", "The church is carved directly into granite and covered by a copper dome that filters natural light. Its acoustics also make it a highly regarded concert venue.", "L'église est creusée directement dans le granit et couverte d'un dôme de cuivre qui diffuse la lumière naturelle. Son acoustique en fait aussi une salle de concert très appréciée.", "La iglesia está excavada directamente en el granito y cubierta por una cúpula de cobre que filtra la luz natural. Su acústica también la convierte en una sala de conciertos muy valorada."), 60.1729, 24.9252, 50, "chiesa", "https://www.temppeliaukionkirkko.fi/en"),
    _A(203, "toolo_culture", 1, ("Monumento a Sibelius", "Sibelius Monument", "Monument Sibelius", "Monumento a Sibelius"),
       ("Oltre seicento tubi d'acciaio compongono il tributo astratto al compositore Jean Sibelius. Il vicino ritratto scolpito aiuta a leggere l'opera e il parco offre una piacevole pausa sul mare.", "More than six hundred steel pipes form the abstract tribute to composer Jean Sibelius. The nearby sculpted portrait helps interpret it, while the surrounding park offers a pleasant seaside break.", "Plus de six cents tubes d'acier composent cet hommage abstrait au compositeur Jean Sibelius. Le portrait sculpté voisin aide à comprendre l'œuvre et le parc offre une agréable pause au bord de l'eau.", "Más de seiscientos tubos de acero forman el homenaje abstracto al compositor Jean Sibelius. El retrato esculpido cercano ayuda a interpretar la obra y el parque ofrece una agradable pausa junto al mar."), 60.1820, 24.9139, 40, "monumento"),
    _A(203, "toolo_culture", 1, ("Biblioteca centrale Oodi", "Oodi Central Library", "Bibliothèque centrale Oodi", "Biblioteca central Oodi"),
       ("Oodi è una biblioteca civica contemporanea con libri, laboratori, sale pubbliche e una terrazza affacciata sul Parlamento. È uno degli esempi più chiari del modo finlandese di intendere i servizi pubblici.", "Oodi is a contemporary civic library with books, workshops, public rooms and a terrace facing Parliament. It is one of the clearest examples of Finland's approach to public services.", "Oodi est une bibliothèque civique contemporaine avec livres, ateliers, espaces publics et terrasse face au Parlement. Elle illustre particulièrement bien la conception finlandaise des services publics.", "Oodi es una biblioteca cívica contemporánea con libros, talleres, espacios públicos y una terraza frente al Parlamento. Es uno de los ejemplos más claros de la concepción finlandesa de los servicios públicos."), 60.1731, 24.9382, 55, "biblioteca", "https://oodihelsinki.fi/en/"),
    _A(203, "toolo_culture", 2, ("Museo Nazionale della Finlandia", "National Museum of Finland", "Musée national de Finlande", "Museo Nacional de Finlandia"),
       ("Il museo racconta la storia del paese dalla preistoria alla Finlandia moderna in un edificio ispirato ai castelli medievali. Verifica l'apertura prima della visita perché il complesso è interessato da un importante rinnovamento.", "The museum traces the country from prehistory to modern Finland in a building inspired by medieval castles. Check opening status before visiting because the complex is undergoing a major renovation.", "Le musée retrace l'histoire du pays de la préhistoire à la Finlande moderne dans un bâtiment inspiré des châteaux médiévaux. Vérifiez son ouverture, car le complexe fait l'objet d'une rénovation majeure.", "El museo recorre la historia del país desde la prehistoria hasta la Finlandia moderna en un edificio inspirado en castillos medievales. Conviene comprobar su apertura porque el complejo está inmerso en una gran renovación."), 60.1750, 24.9310, 90, "museo", "https://www.kansallismuseo.fi/en/"),
    _A(203, "toolo_culture", 2, ("Finlandia Hall", "Finlandia Hall", "Maison Finlandia", "Finlandia Hall"),
       ("Il centro congressi progettato da Alvar Aalto è uno dei riferimenti dell'architettura modernista finlandese. La facciata chiara dialoga con la baia di Töölö e gli interni si visitano soprattutto con eventi o tour.", "Alvar Aalto's congress hall is a landmark of Finnish modernist architecture. Its pale façade faces Töölö Bay, while interiors are mainly accessible during events or guided visits.", "Le palais des congrès conçu par Alvar Aalto est une référence de l'architecture moderniste finlandaise. Sa façade claire dialogue avec la baie de Töölö et les intérieurs se découvrent surtout lors d'événements ou de visites guidées.", "El centro de congresos diseñado por Alvar Aalto es un referente de la arquitectura modernista finlandesa. Su fachada clara dialoga con la bahía de Töölö y los interiores se visitan principalmente durante eventos o visitas guiadas."), 60.1759, 24.9335, 35, "architettura", "https://finlandiatalo.fi/en/"),
    _A(203, "toolo_culture", 3, ("Parlamento finlandese", "Finnish Parliament House", "Parlement finlandais", "Parlamento de Finlandia"),
       ("La facciata in granito e la grande scalinata esprimono il volto istituzionale della Finlandia indipendente. L'esterno si osserva facilmente da Kansalaistori; le visite interne dipendono dal calendario parlamentare.", "The granite façade and broad staircase express the institutional face of independent Finland. The exterior is easily viewed from Kansalaistori, while interior visits depend on the parliamentary calendar.", "La façade de granit et le grand escalier expriment le visage institutionnel de la Finlande indépendante. L'extérieur s'observe facilement depuis Kansalaistori; les visites intérieures dépendent du calendrier parlementaire.", "La fachada de granito y la gran escalinata expresan el rostro institucional de la Finlandia independiente. El exterior se contempla bien desde Kansalaistori; las visitas interiores dependen del calendario parlamentario."), 60.1727, 24.9337, 25, "palazzo istituzionale"),

    _A(204, "design_south", 1, ("Museo del Design", "Design Museum", "Musée du Design", "Museo del Diseño"),
       ("La collezione segue l'evoluzione del design finlandese dagli oggetti industriali alla moda e alla grafica. È il punto di partenza più efficace per riconoscere poi il design nella vita quotidiana della città.", "The collection follows Finnish design from industrial objects to fashion and graphics. It is the most effective starting point for recognising design throughout the city's everyday life.", "La collection suit l'évolution du design finlandais des objets industriels à la mode et au graphisme. C'est le meilleur point de départ pour reconnaître ensuite le design dans la vie quotidienne de la ville.", "La colección recorre el diseño finlandés desde los objetos industriales hasta la moda y el grafismo. Es el mejor punto de partida para reconocer después el diseño en la vida cotidiana de la ciudad."), 60.1631, 24.9460, 90, "museo", "https://www.designmuseum.fi/en/"),
    _A(204, "design_south", 1, ("Löyly", "Löyly", "Löyly", "Löyly"),
       ("Il complesso in legno sul Baltico combina sauna pubblica, ristorante e accesso diretto al mare. Per la sauna è indispensabile prenotare e portare il costume; l'esterno resta interessante anche senza ingresso.", "This timber complex on the Baltic combines public sauna, restaurant and direct sea access. Sauna booking and swimwear are essential; the exterior remains worthwhile without admission.", "Ce complexe en bois sur la Baltique réunit sauna public, restaurant et accès direct à la mer. La réservation et le maillot sont indispensables pour le sauna; l'extérieur vaut aussi le détour sans entrée.", "Este complejo de madera junto al Báltico combina sauna pública, restaurante y acceso directo al mar. Para la sauna es imprescindible reservar y llevar bañador; el exterior también merece la visita sin entrada."), 60.1506, 24.9300, 90, "sauna", "https://www.loylyhelsinki.fi/en"),
    _A(204, "design_south", 2, ("Museo dell'Architettura Finlandese", "Museum of Finnish Architecture", "Musée de l'Architecture finlandaise", "Museo de Arquitectura Finlandesa"),
       ("Mostre e archivi spiegano come il modernismo, il legno e il rapporto con il paesaggio abbiano formato l'architettura finlandese. Il museo è vicino al Design Museum e i due si combinano bene nella stessa visita.", "Exhibitions and archives explain how modernism, timber and landscape shaped Finnish architecture. It stands beside the Design Museum and the two work well as a combined visit.", "Expositions et archives expliquent comment modernisme, bois et paysage ont façonné l'architecture finlandaise. Le musée se trouve près du Design Museum et les deux se visitent facilement ensemble.", "Exposiciones y archivos explican cómo el modernismo, la madera y el paisaje dieron forma a la arquitectura finlandesa. Está junto al Museo del Diseño y ambos se combinan bien en una misma visita."), 60.1632, 24.9481, 70, "museo", "https://www.mfa.fi/en/"),
    _A(204, "design_south", 2, ("Parco Kaivopuisto", "Kaivopuisto Park", "Parc Kaivopuisto", "Parque Kaivopuisto"),
       ("Il grande parco costiero alterna prati, rocce e viste sulle isole dell'arcipelago. È particolarmente vivo nelle giornate limpide e durante Vappu, ma il vento può essere forte fuori dall'estate.", "The large coastal park mixes lawns, rocks and views over the archipelago. It is especially lively on clear days and during Vappu, though winds can be strong outside summer.", "Ce grand parc côtier mêle pelouses, rochers et vues sur l'archipel. Il est particulièrement animé par beau temps et pendant Vappu, mais le vent peut être fort hors saison.", "El gran parque costero combina praderas, rocas y vistas al archipiélago. Está especialmente animado en días despejados y durante Vappu, aunque el viento puede ser fuerte fuera del verano."), 60.1552, 24.9552, 60, "parco"),
    _A(204, "design_south", 3, ("Mercato coperto di Hietalahti", "Hietalahti Market Hall", "Marché couvert de Hietalahti", "Mercado cubierto de Hietalahti"),
       ("La storica hall ospita ristorazione informale e piccoli operatori in un quartiere creativo. Nella bella stagione il mercato delle pulci esterno aggiunge un volto molto locale alla visita.", "The historic hall hosts casual food counters and small operators in a creative district. In warmer months, the outdoor flea market adds a distinctly local dimension.", "La halle historique accueille restauration informelle et petits commerçants dans un quartier créatif. Aux beaux jours, le marché aux puces extérieur ajoute une dimension très locale.", "El mercado histórico alberga restauración informal y pequeños negocios en un barrio creativo. En los meses cálidos, el mercadillo exterior añade una dimensión muy local."), 60.1620, 24.9297, 45, "mercato"),
    _A(204, "design_south", 3, ("Chiesa di San Giovanni", "St John's Church", "Église Saint-Jean", "Iglesia de San Juan"),
       ("Le due alte guglie neogotiche segnano il profilo del Design District. L'interno ampio e luminoso è anche una delle principali sedi concertistiche ecclesiastiche della città.", "Its twin Gothic Revival spires define the Design District skyline. The spacious, luminous interior is also one of the city's principal church concert venues.", "Ses deux hautes flèches néogothiques marquent le paysage du Design District. L'intérieur vaste et lumineux est aussi l'un des principaux lieux de concerts religieux de la ville.", "Sus dos altas agujas neogóticas definen el perfil del Design District. El interior amplio y luminoso es también uno de los principales espacios de conciertos religiosos de la ciudad."), 60.1613, 24.9460, 30, "chiesa"),
]

