_ZONE_COPY = {
 "kallio_linnanmaki": ("Questa tappa mostra il lato quotidiano e creativo di Kallio, tra mercati, cultura popolare e spazi frequentati dai residenti.", "This stop reveals Kallio's everyday creative character through markets, popular culture and spaces used by residents.", "Cette étape révèle le caractère quotidien et créatif de Kallio entre marchés, culture populaire et lieux fréquentés par les habitants.", "Esta parada muestra el carácter cotidiano y creativo de Kallio entre mercados, cultura popular y espacios frecuentados por los vecinos."),
 "katajanokka_kruununhaka": ("La visita collega il porto alla storia architettonica e istituzionale di Helsinki, con scorci ravvicinati sul Baltico.", "The visit links the harbour with Helsinki's architectural and institutional history, with close views over the Baltic.", "La visite relie le port à l'histoire architecturale et institutionnelle d'Helsinki, avec des vues proches sur la Baltique.", "La visita conecta el puerto con la historia arquitectónica e institucional de Helsinki, con vistas cercanas al Báltico."),
 "seurasaari_munkkiniemi": ("Questa tappa unisce natura, architettura finlandese e memoria del Novecento in una zona tranquilla a ovest del centro.", "This stop combines nature, Finnish architecture and twentieth-century history in a calm area west of the centre.", "Cette étape associe nature, architecture finlandaise et mémoire du XXe siècle dans un secteur calme à l'ouest du centre.", "Esta parada combina naturaleza, arquitectura finlandesa y memoria del siglo XX en una zona tranquila al oeste del centro."),
 "islands_arabia": ("La tappa amplia la visita oltre il centro e mostra il rapporto di Helsinki con isole, natura urbana, design e storia industriale.", "This stop extends the visit beyond the centre and shows Helsinki's relationship with islands, urban nature, design and industrial history.", "Cette étape prolonge la visite au-delà du centre et montre le rapport d'Helsinki aux îles, à la nature urbaine, au design et à l'histoire industrielle.", "Esta parada amplía la visita más allá del centro y muestra la relación de Helsinki con las islas, la naturaleza urbana, el diseño y la historia industrial."),
}
_DETAILS = {
 "Mercato coperto di Hakaniemi":("La hall rinnovata riunisce pesce, pane, prodotti finlandesi e piccoli locali su due livelli.","The renovated hall gathers fish, bread, Finnish produce and small eateries across two floors.","La halle rénovée réunit poisson, pain, produits finlandais et petites tables sur deux niveaux.","El mercado renovado reúne pescado, pan, productos finlandeses y pequeños locales en dos plantas."),
 "Chiesa di Kallio":("La torre in granito è un riferimento visivo del quartiere e ospita concerti grazie alla notevole acustica.","Its granite tower is a district landmark and hosts concerts thanks to its notable acoustics.","Sa tour de granit est un repère du quartier et accueille des concerts grâce à son acoustique remarquable.","Su torre de granito es un referente del barrio y acoge conciertos gracias a su notable acústica."),
 "Sauna Kotiharju":("È l'ultima sauna pubblica tradizionale di Helsinki ancora riscaldata a legna, con spogliatoi separati.","It is Helsinki's last traditional public sauna still heated by wood, with separate changing areas.","C'est le dernier sauna public traditionnel d'Helsinki encore chauffé au bois, avec vestiaires séparés.","Es la última sauna pública tradicional de Helsinki todavía calentada con leña, con vestuarios separados."),
 "Parco divertimenti Linnanmäki":("Il parco sostiene la tutela dell'infanzia e combina giostre moderne con lo storico ottovolante in legno.","The park supports child welfare and combines modern rides with its historic wooden roller coaster.","Le parc soutient la protection de l'enfance et associe attractions modernes et montagnes russes historiques en bois.","El parque apoya la protección infantil y combina atracciones modernas con su histórica montaña rusa de madera."),
 "SEA LIFE Helsinki":("Il percorso coperto presenta ecosistemi marini e un tunnel oceanico, risultando utile soprattutto con maltempo.","The indoor route presents marine ecosystems and an ocean tunnel, making it especially useful in poor weather.","Le parcours intérieur présente des écosystèmes marins et un tunnel océanique, particulièrement utile par mauvais temps.","El recorrido cubierto presenta ecosistemas marinos y un túnel oceánico, especialmente útil con mal tiempo."),
 "Baia di Töölönlahti e Tokoinranta":("Il sentiero sul bordo dell'acqua collega Kallio ai principali edifici culturali intorno alla baia.","The waterside path links Kallio with the major cultural buildings around the bay.","Le chemin au bord de l'eau relie Kallio aux grands édifices culturels autour de la baie.","El sendero junto al agua conecta Kallio con los principales edificios culturales de la bahía."),
 "Allas Sea Pool":("Piscine riscaldate e sauna si affacciano sul porto, permettendo di nuotare all'aperto in gran parte dell'anno.","Heated pools and saunas face the harbour, allowing outdoor swimming through much of the year.","Piscines chauffées et saunas donnent sur le port et permettent de nager dehors une grande partie de l'année.","Piscinas climatizadas y saunas miran al puerto y permiten nadar al aire libre gran parte del año."),
 "Architettura Art Nouveau di Katajanokka":("Le strade residenziali conservano uno dei complessi Jugend più ricchi della città, tra torrette e motivi naturali.","Residential streets preserve one of the city's richest Jugend ensembles, with turrets and nature motifs.","Les rues résidentielles conservent l'un des plus riches ensembles Jugend de la ville, entre tourelles et motifs naturels.","Las calles residenciales conservan uno de los conjuntos Jugend más ricos de la ciudad, con torres y motivos naturales."),
 "SkyWheel Helsinki":("La ruota offre una lettura rapida del porto, delle cattedrali e delle isole vicine da cabine chiuse.","The wheel offers a quick view of the harbour, cathedrals and nearby islands from enclosed cabins.","La roue offre depuis ses cabines fermées une lecture rapide du port, des cathédrales et des îles proches.","La noria ofrece desde cabinas cerradas una vista rápida del puerto, las catedrales y las islas cercanas."),
 "Parco Tove Jansson":("Il piccolo parco porta il nome della creatrice dei Mumin e crea una pausa verde sotto Uspenski.","The small park bears the Moomins creator's name and offers a green pause below Uspenski.","Ce petit parc porte le nom de la créatrice des Moumines et offre une pause verte sous Ouspenski.","El pequeño parque lleva el nombre de la creadora de los Mumin y ofrece una pausa verde bajo Uspenski."),
 "Casa degli Stati":("L'edificio neorinascimentale del 1891 conserva un ruolo cerimoniale nel quartiere governativo.","The 1891 Renaissance Revival building retains a ceremonial role in the government district.","L'édifice néo-Renaissance de 1891 conserve un rôle cérémoniel dans le quartier gouvernemental.","El edificio neorrenacentista de 1891 conserva una función ceremonial en el barrio gubernamental."),
 "Museo della Banca di Finlandia":("L'esposizione gratuita spiega moneta, inflazione e storia economica finlandese con strumenti interattivi.","The free exhibition explains money, inflation and Finnish economic history through interactive displays.","L'exposition gratuite explique monnaie, inflation et histoire économique finlandaise avec des dispositifs interactifs.","La exposición gratuita explica dinero, inflación e historia económica finlandesa mediante recursos interactivos."),
 "Isola di Seurasaari":("Un ponte pedonale conduce a sentieri boscosi e coste rocciose frequentate anche dalla fauna locale.","A footbridge leads to wooded paths and rocky shores also frequented by local wildlife.","Une passerelle mène à des sentiers boisés et des côtes rocheuses fréquentées par la faune locale.","Un puente peatonal conduce a senderos boscosos y costas rocosas frecuentadas por la fauna local."),
 "Museo all'aperto di Seurasaari":("Edifici rurali trasferiti da tutta la Finlandia illustrano abitazioni, mestieri e tradizioni regionali; l'apertura è stagionale.","Rural buildings moved from across Finland illustrate homes, trades and regional traditions; opening is seasonal.","Des bâtiments ruraux venus de toute la Finlande illustrent habitat, métiers et traditions régionales; l'ouverture est saisonnière.","Edificios rurales trasladados de toda Finlandia muestran viviendas, oficios y tradiciones regionales; la apertura es estacional."),
 "Tamminiemi":("La casa museo conserva gli ambienti del presidente Urho Kekkonen e racconta la politica finlandese del dopoguerra.","The house museum preserves President Urho Kekkonen's rooms and explores post-war Finnish politics.","La maison-musée conserve les pièces du président Urho Kekkonen et raconte la politique finlandaise d'après-guerre.","La casa museo conserva las estancias del presidente Urho Kekkonen y explica la política finlandesa de posguerra."),
 "Casa di Alvar Aalto":("Casa e studio domestico mostrano come Aalto integrasse luce, materiali naturali e vita familiare.","The home and domestic studio show how Aalto integrated light, natural materials and family life.","La maison et l'atelier domestique montrent comment Aalto associait lumière, matériaux naturels et vie familiale.","La casa y el estudio doméstico muestran cómo Aalto integraba luz, materiales naturales y vida familiar."),
 "Studio Aalto":("Il luminoso atelier del 1955 conserva spazi di lavoro, arredi e il cortile ad anfiteatro dell'architetto.","The bright 1955 studio preserves workspaces, furniture and the architect's amphitheatre courtyard.","L'atelier lumineux de 1955 conserve espaces de travail, mobilier et cour en amphithéâtre de l'architecte.","El luminoso estudio de 1955 conserva espacios de trabajo, mobiliario y el patio en anfiteatro del arquitecto."),
 "Lungomare di Munkkiniemi":("La passeggiata offre un volto residenziale di Helsinki tra spiaggia, ville, caffè e tram verso il centro.","The promenade reveals residential Helsinki through a beach, villas, cafés and trams to the centre.","La promenade révèle la Helsinki résidentielle entre plage, villas, cafés et tramways vers le centre.","El paseo muestra la Helsinki residencial entre playa, villas, cafeterías y tranvías al centro."),
 "Isola di Vallisaari":("Ex isola militare, oggi apre sentieri panoramici tra fortificazioni e habitat protetti; accessi e stagione vanno verificati.","Formerly military, the island now opens scenic trails among fortifications and protected habitats; check season and access.","Ancienne île militaire, elle ouvre aujourd'hui des sentiers panoramiques entre fortifications et habitats protégés; vérifiez saison et accès.","Antigua isla militar, hoy ofrece senderos panorámicos entre fortificaciones y hábitats protegidos; conviene comprobar temporada y acceso."),
 "Zoo di Korkeasaari":("Lo zoo insulare del 1889 concentra specie nordiche e programmi di conservazione, raggiungibili anche via traghetto stagionale.","The 1889 island zoo focuses on northern species and conservation programmes and is also reached by seasonal ferry.","Le zoo insulaire de 1889 privilégie espèces nordiques et programmes de conservation, avec aussi un ferry saisonnier.","El zoológico insular de 1889 se centra en especies nórdicas y conservación, y también se alcanza en ferri estacional."),
 "Rapide di Vanhankaupunginkoski":("Le rapide segnano il luogo in cui Helsinki fu fondata nel 1550 e oggi uniscono archeologia industriale e natura.","The rapids mark where Helsinki was founded in 1550 and now combine industrial archaeology with nature.","Les rapides marquent le lieu de fondation d'Helsinki en 1550 et associent aujourd'hui archéologie industrielle et nature.","Los rápidos marcan el lugar donde Helsinki fue fundada en 1550 y hoy combinan arqueología industrial y naturaleza."),
 "Arabia Design Centre":("L'area della storica fabbrica Arabia presenta ceramica finlandese, mostre di design e opere d'arte pubblica.","The historic Arabia factory area presents Finnish ceramics, design exhibitions and public artworks.","Le secteur de l'ancienne usine Arabia présente céramique finlandaise, expositions de design et œuvres publiques.","La zona de la histórica fábrica Arabia presenta cerámica finlandesa, exposiciones de diseño y arte público."),
 "Passerelle di Lammassaari":("Le passerelle attraversano canneti e zone umide fino a capanni di osservazione; in primavera è importante restare sui percorsi.","Boardwalks cross reeds and wetlands to bird hides; in spring it is important to remain on marked paths.","Les passerelles traversent roselières et zones humides jusqu'aux observatoires; au printemps, restez sur les chemins.","Las pasarelas atraviesan carrizales y humedales hasta observatorios; en primavera es importante permanecer en los senderos."),
 "Museo della Tecnologia":("Installato presso antichi impianti idrici, racconta industrializzazione, innovazione e tecnologia quotidiana in Finlandia.","Set in former waterworks, it traces industrialisation, innovation and everyday technology in Finland.","Installé dans d'anciens équipements hydrauliques, il raconte industrialisation, innovation et technologie quotidienne en Finlande.","Instalado en antiguas obras hidráulicas, explica la industrialización, la innovación y la tecnología cotidiana en Finlandia."),
}
for block, zone, level, names, lat, lon, minutes, kind in _MORE:
    descriptions = tuple(f"{_ZONE_COPY[zone][index]} {_DETAILS[names[0]][index]}" for index in range(4))
    ATTRACTIONS.append(_A(block, zone, level, names, descriptions, lat, lon, minutes, kind))


