FOODS_BY_CITY = [
 {"name":"Lohikeitto","name_en":"Finnish Salmon Soup","name_fr":"Soupe finlandaise au saumon","name_es":"Sopa finlandesa de salmón","description":"Zuppa cremosa ma delicata con salmone, patate, porro e aneto, servita fumante con pane di segale. Il brodo deve restare pulito e il pesce morbido: è uno dei piatti più rassicuranti nelle giornate fredde sul porto.","description_en":"A creamy yet delicate soup of salmon, potatoes, leek and dill, served steaming with rye bread. The broth should remain clean and the fish tender: it is one of the most comforting dishes on cold harbour days.","description_fr":"Soupe crémeuse mais délicate au saumon, pommes de terre, poireau et aneth, servie fumante avec du pain de seigle. Le bouillon doit rester net et le poisson tendre: c'est l'un des plats les plus réconfortants lors des journées froides au port.","description_es":"Sopa cremosa pero delicada de salmón, patata, puerro y eneldo, servida humeante con pan de centeno. El caldo debe quedar limpio y el pescado tierno: es uno de los platos más reconfortantes en los días fríos del puerto.","ingredients":["salmone","patate","porro","panna","aneto"],"ingredients_en":["salmon","potatoes","leek","cream","dill"],"ingredients_fr":["saumon","pommes de terre","poireau","crème","aneth"],"ingredients_es":["salmón","patatas","puerro","nata","eneldo"],"places":["Story Old Market Hall Helsinki","Restaurant Savotta Helsinki","Soppakeittio Hakaniemi Helsinki"]},
 {"name":"Karjalanpiirakka","name_en":"Karelian Pies","name_fr":"Pirogues caréliennes","name_es":"Pasteles de Carelia","description":"Sottili gusci di segale racchiudono un ripieno morbido di riso e vengono completati con munavoi, burro montato con uovo sodo. Il contrasto tra crosta rustica e ripieno cremoso li rende ideali a colazione o come spuntino salato.","description_en":"Thin rye shells hold a soft rice filling and are finished with munavoi, butter whipped with boiled egg. The contrast between rustic crust and creamy centre makes them ideal for breakfast or a savoury snack.","description_fr":"De fines coques de seigle renferment une garniture moelleuse au riz et sont accompagnées de munavoi, beurre mélangé à de l'œuf dur. Le contraste entre croûte rustique et cœur crémeux les rend idéales au petit déjeuner ou en encas salé.","description_es":"Finas cortezas de centeno contienen un relleno suave de arroz y se completan con munavoi, mantequilla batida con huevo cocido. El contraste entre la corteza rústica y el centro cremoso las hace ideales para desayunar o como tentempié salado.","ingredients":["farina di segale","riso","latte","burro","uovo"],"ingredients_en":["rye flour","rice","milk","butter","egg"],"ingredients_fr":["farine de seigle","riz","lait","beurre","œuf"],"ingredients_es":["harina de centeno","arroz","leche","mantequilla","huevo"],"places":["Cafe Engel Helsinki","Ekberg Helsinki","Fazer Cafe Kluuvikatu Helsinki"]},
 {"name":"Poronkäristys","name_en":"Sauteed Reindeer","name_fr":"Renne sauté","name_es":"Reno salteado","description":"Fettine sottili di renna vengono stufate lentamente e servite con purè, mirtilli rossi e cetriolini. È una specialità della Lapponia molto presente nei ristoranti tradizionali della capitale, intensa ma equilibrata dall'acidità dei contorni.","description_en":"Thin slices of reindeer are slowly braised and served with mash, lingonberries and pickles. A Lapland speciality common in the capital's traditional restaurants, it is rich yet balanced by the acidity of its accompaniments.","description_fr":"De fines tranches de renne mijotent lentement avant d'être servies avec purée, airelles et cornichons. Cette spécialité lapone, fréquente dans les restaurants traditionnels de la capitale, est riche mais équilibrée par l'acidité des garnitures.","description_es":"Finas lonchas de reno se guisan lentamente y se sirven con puré, arándanos rojos y pepinillos. Esta especialidad lapona, habitual en los restaurantes tradicionales de la capital, es intensa pero queda equilibrada por la acidez de los acompañamientos.","ingredients":["carne di renna","patate","mirtilli rossi","cetriolini","burro"],"ingredients_en":["reindeer","potatoes","lingonberries","pickles","butter"],"ingredients_fr":["renne","pommes de terre","airelles","cornichons","beurre"],"ingredients_es":["reno","patatas","arándanos rojos","pepinillos","mantequilla"],"places":["Lappi Ravintola Helsinki","Restaurant Savotta Helsinki","Restaurant Zetor Helsinki"]},
 {"name":"Paistetut silakat","name_en":"Fried Baltic Herring","name_fr":"Hareng de la Baltique frit","name_es":"Arenque del Báltico frito","description":"Piccoli filetti di aringa baltica vengono impanati leggermente e fritti, poi accompagnati da patate, aneto e salse acidule. È un sapore profondamente legato al porto di Helsinki e dà il meglio quando il pesce resta succoso sotto la crosta.","description_en":"Small Baltic herring fillets are lightly breaded and fried, then served with potatoes, dill and sharp sauces. The flavour is deeply tied to Helsinki's harbour and is best when the fish remains juicy beneath its crust.","description_fr":"De petits filets de hareng de la Baltique sont légèrement panés et frits, puis servis avec pommes de terre, aneth et sauces acidulées. Cette saveur est intimement liée au port d'Helsinki et le poisson doit rester juteux sous sa croûte.","description_es":"Pequeños filetes de arenque del Báltico se empanan ligeramente y se fríen, acompañados de patatas, eneldo y salsas ácidas. Es un sabor muy ligado al puerto de Helsinki y resulta mejor cuando el pescado queda jugoso bajo la corteza.","ingredients":["aringa baltica","farina di segale","patate","aneto","limone"],"ingredients_en":["Baltic herring","rye flour","potatoes","dill","lemon"],"ingredients_fr":["hareng de la Baltique","farine de seigle","pommes de terre","aneth","citron"],"ingredients_es":["arenque del Báltico","harina de centeno","patatas","eneldo","limón"],"places":["Restaurant Sea Horse Helsinki","Restaurant Salve Helsinki","Restaurant Savotta Helsinki"]},
 {"name":"Korvapuusti","name_en":"Finnish Cinnamon Bun","name_fr":"Brioche finlandaise à la cannelle","name_es":"Bollo finlandés de canela","description":"La brioche finlandese alla cannella è profumata di cardamomo, arrotolata nella caratteristica forma schiacciata e coperta di zucchero perlato. Va cercata fresca di forno: insieme al caffè rappresenta una delle pause più quotidiane della città.","description_en":"The Finnish cinnamon bun is scented with cardamom, rolled into its distinctive pressed shape and topped with pearl sugar. Seek it fresh from the oven: with coffee, it forms one of the city's most everyday rituals.","description_fr":"La brioche finlandaise à la cannelle est parfumée à la cardamome, roulée dans sa forme aplatie caractéristique et couverte de sucre perlé. Il faut la goûter à la sortie du four: avec le café, elle incarne l'une des pauses les plus quotidiennes de la ville.","description_es":"El bollo finlandés de canela lleva cardamomo, se enrolla en su característica forma aplanada y se cubre con azúcar perlado. Conviene probarlo recién horneado: junto con el café representa una de las pausas más cotidianas de la ciudad.","ingredients":["farina","burro","cannella","cardamomo","zucchero perlato"],"ingredients_en":["flour","butter","cinnamon","cardamom","pearl sugar"],"ingredients_fr":["farine","beurre","cannelle","cardamome","sucre perlé"],"ingredients_es":["harina","mantequilla","canela","cardamomo","azúcar perlado"],"places":["Cafe Regatta Helsinki","Ekberg Helsinki","Way Bakery Helsinki"]},
 {"name":"Leipäjuusto e lakka","name_en":"Bread Cheese with Cloudberry","name_fr":"Fromage-pain aux mûres arctiques","name_es":"Queso de pan con mora ártica","description":"Il formaggio fresco cotto sviluppa macchie dorate e una consistenza elastica che scricchiola leggermente sotto i denti. Servito tiepido con confettura di mora artica unisce latte, tostatura e una dolce acidità nordica.","description_en":"This baked fresh cheese develops golden spots and a springy texture that squeaks gently when bitten. Served warm with cloudberry preserve, it combines milkiness, toast and a distinctly Nordic sweet acidity.","description_fr":"Ce fromage frais cuit développe des taches dorées et une texture élastique qui grince légèrement sous la dent. Servi tiède avec de la confiture de mûre arctique, il associe lait, notes grillées et douce acidité nordique.","description_es":"Este queso fresco horneado desarrolla manchas doradas y una textura elástica que cruje ligeramente al morder. Servido templado con confitura de mora ártica, combina leche, tostado y una dulce acidez nórdica.","ingredients":["latte","caglio","sale","mora artica"],"ingredients_en":["milk","rennet","salt","cloudberry"],"ingredients_fr":["lait","présure","sel","mûre arctique"],"ingredients_es":["leche","cuajo","sal","mora ártica"],"places":["Lappi Ravintola Helsinki","Restaurant Savotta Helsinki","Konstan Molja Helsinki"]},
 {"name":"Hernekeitto e pannukakku","name_en":"Pea Soup and Oven Pancake","name_fr":"Soupe de pois et crêpe au four","name_es":"Sopa de guisantes y tortita al horno","description":"Il tradizionale pranzo del giovedì abbina una densa zuppa di piselli, spesso con maiale, a una fetta di pannukakku con confettura. Il passaggio dal salato al dolce racconta bene la cucina domestica e delle mense finlandesi.","description_en":"The traditional Thursday lunch pairs thick pea soup, often with pork, with a slice of oven pancake and jam. The shift from savoury to sweet captures Finnish home and canteen cooking particularly well.","description_fr":"Le déjeuner traditionnel du jeudi associe une soupe épaisse de pois, souvent au porc, à une part de pannukakku avec confiture. Le passage du salé au sucré résume particulièrement bien la cuisine familiale et des cantines finlandaises.","description_es":"El almuerzo tradicional de los jueves combina una sopa espesa de guisantes, a menudo con cerdo, con una porción de pannukakku y mermelada. El paso de salado a dulce resume muy bien la cocina doméstica y de comedor finlandesa.","ingredients":["piselli secchi","maiale","senape","latte","uova"],"ingredients_en":["dried peas","pork","mustard","milk","eggs"],"ingredients_fr":["pois secs","porc","moutarde","lait","œufs"],"ingredients_es":["guisantes secos","cerdo","mostaza","leche","huevos"],"places":["Restaurant Elite Helsinki","Restaurant Sea Horse Helsinki","Restaurant Lasipalatsi Helsinki"]},
 {"name":"Vorschmack","name_en":"Vorschmack","name_fr":"Vorschmack","name_es":"Vorschmack","description":"Carne macinata lentamente con acciughe o aringhe fino a ottenere uno stufato intenso, servito con patate, panna acida e sottaceti. Divenne un classico di Helsinki grazie al maresciallo Mannerheim ed è ancora presente nei ristoranti storici.","description_en":"Meat is slowly cooked with anchovy or herring into an intense stew, served with potatoes, sour cream and pickles. It became a Helsinki classic through Marshal Mannerheim and remains on menus in historic restaurants.","description_fr":"La viande mijote avec anchois ou hareng jusqu'à former un ragoût intense, servi avec pommes de terre, crème aigre et cornichons. Devenu un classique d'Helsinki grâce au maréchal Mannerheim, il figure encore dans les restaurants historiques.","description_es":"La carne se cocina lentamente con anchoa o arenque hasta formar un guiso intenso, servido con patatas, crema agria y encurtidos. Se convirtió en un clásico de Helsinki gracias al mariscal Mannerheim y sigue presente en restaurantes históricos.","ingredients":["manzo","agnello","acciughe","patate","panna acida"],"ingredients_en":["beef","lamb","anchovies","potatoes","sour cream"],"ingredients_fr":["bœuf","agneau","anchois","pommes de terre","crème aigre"],"ingredients_es":["ternera","cordero","anchoas","patatas","crema agria"],"places":["Restaurant Savoy Helsinki","Restaurant Elite Helsinki","Restaurant Sea Horse Helsinki"]},
]


def _fact(icon, titles, bodies):
    return {"icon":icon,"title":titles[0],"title_en":titles[1],"title_fr":titles[2],"title_es":titles[3],"body":bodies[0],"body_en":bodies[1],"body_fr":bodies[2],"body_es":bodies[3]}

_FACT_ROWS = [
 ("🧖",("La sauna è vita quotidiana","Sauna is everyday life","Le sauna fait partie du quotidien","La sauna forma parte de la vida cotidiana"),("In Finlandia la sauna non è un lusso occasionale, ma uno spazio comune di benessere, silenzio e socialità.","In Finland, sauna is not an occasional luxury but a shared space for wellbeing, silence and social life.","En Finlande, le sauna n'est pas un luxe occasionnel mais un espace partagé de bien-être, de silence et de sociabilité.","En Finlandia, la sauna no es un lujo ocasional, sino un espacio compartido de bienestar, silencio y vida social.")),
 ("🏝️",("La città si apre su un arcipelago","The city opens onto an archipelago","La ville s'ouvre sur un archipel","La ciudad se abre a un archipiélago"),("Circa trecento isole rendono traghetti, coste e bagni di mare parte dell'esperienza urbana.","Roughly three hundred islands make ferries, shorelines and sea swimming part of urban life.","Environ trois cents îles font des ferries, des rivages et des bains de mer une partie de la vie urbaine.","Unas trescientas islas hacen que los ferris, las costas y los baños de mar formen parte de la vida urbana.")),
 ("🎨",("Il design è un linguaggio pubblico","Design is a public language","Le design est un langage public","El diseño es un lenguaje público"),("Segnaletica, arredi, biblioteche e trasporti mostrano che il design finlandese non vive soltanto nei musei.","Signs, furniture, libraries and transport show that Finnish design does not live only in museums.","Signalétique, mobilier, bibliothèques et transports montrent que le design finlandais ne vit pas seulement dans les musées.","La señalización, el mobiliario, las bibliotecas y el transporte muestran que el diseño finlandés no vive solo en los museos.")),
 ("🏰",("Suomenlinna racconta tre paesi","Suomenlinna tells the story of three countries","Suomenlinna raconte trois pays","Suomenlinna cuenta la historia de tres países"),("La fortezza conserva strati svedesi, russi e finlandesi che spiegano la posizione strategica di Helsinki sul Baltico.","The fortress preserves Swedish, Russian and Finnish layers that explain Helsinki's strategic Baltic position.","La forteresse conserve des strates suédoises, russes et finlandaises qui expliquent la position stratégique d'Helsinki sur la Baltique.","La fortaleza conserva capas suecas, rusas y finlandesas que explican la posición estratégica de Helsinki en el Báltico.")),
 ("📚",("Oodi interpreta la biblioteca come piazza","Oodi treats the library as a civic square","Oodi conçoit la bibliothèque comme une place civique","Oodi entiende la biblioteca como plaza cívica"),("Laboratori, sale, terrazza e servizi gratuiti trasformano la biblioteca centrale in un vero spazio pubblico.","Workshops, rooms, a terrace and free services turn the central library into a genuine public space.","Ateliers, salles, terrasse et services gratuits transforment la bibliothèque centrale en véritable espace public.","Talleres, salas, terraza y servicios gratuitos convierten la biblioteca central en un auténtico espacio público.")),
 ("🗣️",("La capitale è ufficialmente bilingue","The capital is officially bilingual","La capitale est officiellement bilingue","La capital es oficialmente bilingüe"),("Finlandese e svedese compaiono nella segnaletica; l'inglese è comunque molto diffuso nei servizi turistici.","Finnish and Swedish appear on signs, while English is also widely spoken in visitor services.","Le finnois et le suédois figurent sur la signalétique, tandis que l'anglais est très répandu dans les services touristiques.","El finés y el sueco aparecen en la señalización, mientras que el inglés está muy extendido en los servicios turísticos.")),
 ("☕",("Il caffè scandisce la giornata","Coffee structures the day","Le café rythme la journée","El café marca el ritmo del día"),("Caffè, pulla e korvapuusti sono una ritualità quotidiana, non soltanto una pausa per visitatori.","Coffee, pulla and korvapuusti form an everyday ritual, not merely a visitor's break.","Café, pulla et korvapuusti forment un rituel quotidien, pas seulement une pause touristique.","El café, la pulla y el korvapuusti forman un ritual cotidiano, no solo una pausa turística.")),
 ("🏛️",("Il neoclassico costruì la nuova capitale","Neoclassicism built the new capital","Le néoclassicisme a construit la nouvelle capitale","El neoclasicismo construyó la nueva capital"),("Dopo il 1812 il centro fu ridisegnato per dare a Helsinki un'immagine monumentale coerente con il nuovo ruolo politico.","After 1812 the centre was redesigned to give Helsinki a monumental image suited to its new political role.","Après 1812, le centre fut redessiné pour donner à Helsinki une image monumentale adaptée à son nouveau rôle politique.","Después de 1812, el centro se rediseñó para dar a Helsinki una imagen monumental acorde con su nuevo papel político.")),
 ("🌅",("La luce cambia radicalmente con le stagioni","Light changes radically with the seasons","La lumière change radicalement avec les saisons","La luz cambia radicalmente con las estaciones"),("Le lunghissime giornate estive e il buio invernale modificano orari, ritmi e modo di vivere gli spazi aperti.","Very long summer days and winter darkness reshape schedules, rhythms and the use of outdoor space.","Les très longues journées d'été et l'obscurité hivernale modifient horaires, rythmes et usages des espaces extérieurs.","Los días de verano muy largos y la oscuridad invernal cambian horarios, ritmos y el uso de los espacios abiertos.")),
 ("🌲",("La natura entra nella città","Nature enters the city","La nature entre dans la ville","La naturaleza entra en la ciudad"),("Boschi, rocce, baie e riserve sono raggiungibili con il trasporto pubblico e non vengono percepiti come separati dalla vita urbana.","Forests, rocks, bays and reserves are reachable by public transport and are not perceived as separate from urban life.","Forêts, rochers, baies et réserves sont accessibles en transports publics et ne sont pas perçus comme séparés de la vie urbaine.","Bosques, rocas, bahías y reservas son accesibles en transporte público y no se perciben como algo separado de la vida urbana.")),
 ("🌊",("Il Baltico influenza cucina e clima","The Baltic shapes food and climate","La Baltique façonne cuisine et climat","El Báltico condiciona la cocina y el clima"),("Pesce, vento e ghiaccio marino ricordano continuamente che Helsinki è una capitale portuale del nord.","Fish, wind and sea ice constantly recall that Helsinki is a northern harbour capital.","Poisson, vent et glace de mer rappellent constamment qu'Helsinki est une capitale portuaire du Nord.","El pescado, el viento y el hielo marino recuerdan constantemente que Helsinki es una capital portuaria del norte.")),
 ("🎈",("Vappu riempie parchi e strade","Vappu fills parks and streets","Vappu remplit parcs et rues","Vappu llena parques y calles"),("Tra il 30 aprile e il primo maggio studenti e residenti celebrano la primavera con berretti bianchi, picnic e grandi ritrovi.","On 30 April and 1 May, students and residents celebrate spring with white caps, picnics and large gatherings.","Les 30 avril et 1er mai, étudiants et habitants célèbrent le printemps avec casquettes blanches, pique-niques et grands rassemblements.","El 30 de abril y el 1 de mayo, estudiantes y vecinos celebran la primavera con gorras blancas, pícnics y grandes reuniones.")),
]
CULTURE_FACTS = [_fact(*row) for row in _FACT_ROWS]


