def _neighborhood(index, names, descriptions, tags):
    return {"id":1900+index,"city":CITY_ID,"name":names[0],"name_en":names[1],"name_fr":names[2],"name_es":names[3],"description":descriptions[0],"description_en":descriptions[1],"description_fr":descriptions[2],"description_es":descriptions[3],"vibe_tags":tags,"sort_order":index}

NEIGHBORHOODS = [
 _neighborhood(1,("Kluuvi e Kaartinkaupunki","Kluuvi and Kaartinkaupunki","Kluuvi et Kaartinkaupunki","Kluuvi y Kaartinkaupunki"),("Pro: attrazioni principali raggiungibili a piedi e collegamenti eccellenti. Pro: vasta scelta di ristoranti e servizi. Contro: prezzi elevati. Contro: atmosfera meno residenziale e più affollata di giorno.","Pros: major sights are walkable and transport is excellent. Pros: broad choice of restaurants and services. Cons: high prices. Cons: less residential atmosphere and busy during the day.","Avantages: principaux sites à pied et excellents transports. Avantages: grand choix de restaurants et services. Inconvénients: prix élevés. Inconvénients: ambiance moins résidentielle et forte fréquentation en journée.","Ventajas: principales monumentos a pie y excelentes conexiones. Ventajas: gran oferta de restaurantes y servicios. Desventajas: precios elevados. Desventajas: ambiente menos residencial y mucha actividad diurna."),["centrale","culturale","trasporti"]),
 _neighborhood(2,("Punavuori e Design District","Punavuori and Design District","Punavuori et Design District","Punavuori y Design District"),("Pro: quartiere creativo con boutique, caffè e ottima ristorazione. Pro: centro e mare sono vicini. Contro: hotel generalmente costosi. Contro: alcune strade sono silenziose e poco servite la sera.","Pros: creative district with boutiques, cafés and strong dining. Pros: close to both centre and sea. Cons: hotels are generally expensive. Cons: some streets become quiet and less served at night.","Avantages: quartier créatif, boutiques, cafés et très bonne restauration. Avantages: proche du centre et de la mer. Inconvénients: hôtels généralement chers. Inconvénients: certaines rues sont calmes et moins desservies le soir.","Ventajas: barrio creativo con tiendas, cafeterías y buena gastronomía. Ventajas: cerca del centro y del mar. Desventajas: hoteles generalmente caros. Desventajas: algunas calles quedan tranquilas y con menos servicios por la noche."),["design","gastronomia","mare"]),
 _neighborhood(3,("Katajanokka e Kruununhaka","Katajanokka and Kruununhaka","Katajanokka et Kruununhaka","Katajanokka y Kruununhaka"),("Pro: architettura storica e atmosfera tranquilla accanto al porto. Pro: facile accesso al centro e ai traghetti. Contro: vita notturna limitata. Contro: meno opzioni economiche per mangiare.","Pros: historic architecture and calm harbour atmosphere. Pros: easy access to the centre and ferries. Cons: limited nightlife. Cons: fewer inexpensive dining options.","Avantages: architecture historique et calme près du port. Avantages: accès facile au centre et aux ferries. Inconvénients: vie nocturne limitée. Inconvénients: moins d'options économiques pour manger.","Ventajas: arquitectura histórica y ambiente tranquilo junto al puerto. Ventajas: fácil acceso al centro y los ferris. Desventajas: vida nocturna limitada. Desventajas: menos opciones económicas para comer."),["tranquillo","porto","architettura"]),
 _neighborhood(4,("Kallio e Hakaniemi","Kallio and Hakaniemi","Kallio et Hakaniemi","Kallio y Hakaniemi"),("Pro: vita locale, bar e ristoranti con prezzi più vari. Pro: tram e metro rendono rapido il centro. Contro: più rumore nel fine settimana. Contro: meno vicino alle attrazioni classiche del porto.","Pros: local life, bars and restaurants across a wider price range. Pros: trams and metro give quick access to the centre. Cons: more weekend noise. Cons: farther from the classic harbour sights.","Avantages: vie locale, bars et restaurants à prix variés. Avantages: tramways et métro rejoignent vite le centre. Inconvénients: plus de bruit le week-end. Inconvénients: plus loin des sites classiques du port.","Ventajas: vida local, bares y restaurantes con precios variados. Ventajas: tranvías y metro conectan rápido con el centro. Desventajas: más ruido los fines de semana. Desventajas: más lejos de los monumentos clásicos del puerto."),["vita notturna","locale","metro"]),
 _neighborhood(5,("Töölö","Töölö","Töölö","Töölö"),("Pro: zona elegante, verde e vicina a musei e baia. Pro: tram frequenti verso il centro. Contro: meno ristoranti aperti fino a tardi. Contro: alcune attrazioni del porto richiedono un trasferimento.","Pros: elegant green area near museums and the bay. Pros: frequent trams to the centre. Cons: fewer late-opening restaurants. Cons: some harbour sights require a transfer.","Avantages: secteur élégant et verdoyant près des musées et de la baie. Avantages: tramways fréquents vers le centre. Inconvénients: moins de restaurants ouverts tard. Inconvénients: certains sites du port demandent un trajet.","Ventajas: zona elegante y verde cerca de museos y la bahía. Ventajas: tranvías frecuentes al centro. Desventajas: menos restaurantes abiertos hasta tarde. Desventajas: algunos lugares del puerto requieren desplazamiento."),["verde","culturale","tranquillo"]),
 _neighborhood(6,("Munkkiniemi","Munkkiniemi","Munkkiniemi","Munkkiniemi"),("Pro: atmosfera residenziale, mare e architettura di Alvar Aalto. Pro: ottima tranquillità notturna. Contro: distante dal centro e dal porto. Contro: scelta ridotta di ristoranti e vita serale.","Pros: residential atmosphere, sea and Alvar Aalto architecture. Pros: excellent night-time quiet. Cons: far from the centre and harbour. Cons: limited dining and evening life.","Avantages: ambiance résidentielle, mer et architecture d'Alvar Aalto. Avantages: grande tranquillité nocturne. Inconvénients: loin du centre et du port. Inconvénients: choix réduit de restaurants et sorties.","Ventajas: ambiente residencial, mar y arquitectura de Alvar Aalto. Ventajas: excelente tranquilidad nocturna. Desventajas: lejos del centro y del puerto. Desventajas: oferta reducida de restaurantes y vida nocturna."),["residenziale","mare","tranquillo"]),
]
